UPDATE PLAYERS
SET 
	NAME_KOR = #{nameKor, jdbcType=VARCHAR},
	NATIONALITY_KOR = #{nationalityKor, jdbcType=VARCHAR}
WHERE PLAYER_ID = #{playerId}

UPDATE STAFFS
SET 
	NAME_KOR = #{nameKor, jdbcType=VARCHAR},
	NATIONALITY_KOR = #{nationalityKor, jdbcType=VARCHAR}
WHERE STAFF_ID = #{staffId}

mapper.select:
SELECT ts.TEAM_ID, ts.SEASON, ts.CURRENT_RANK, ts.MATCHES_PLAYED, ts.WINS, ts.DRAWS, ts.LOSSES, ts.POINTS, ts.GOALS_FOR, ts.GOALS_AGAINST, ts.GOAL_DIFF, ts.YELLOW_CARDS, ts.RED_CARDS, ts.UPDATED_AT, t.TEAM_NAME, t.EMBLEM_URL FROM TEAM_STATS ts JOIN TEAMS t ON ts.TEAM_ID = t.TEAM_ID WHERE ts.TEAM_ID = #{teamId}
AND ts.SEASON = #{season}
ORDER BY ts.SEASON DESC FETCH FIRST 1 ROWS ONLY
